1	import type { ImageProxyOptions, PictureSourceUrls, ResponsivePictureSourceUrls } from "types/common";
2	
3	const ABSOLUTE_URL_REGEX = /^https?:\/\//i;
4	const CACHE_PARAM = "v";
5	const MAX_URL_LENGTH = 2048;
6	
7	function sanitizeUrlCandidate(imageUrl: string | null | undefined): string {
8	  if (!imageUrl || typeof imageUrl !== "string") {
9	    return "";
10	  }
11	  return imageUrl.trim();
12	}
13	
14	/**
15	 * Check if URL looks like a legacy file handler BEFORE normalization.
16	 * Used to skip aggressive normalization (like double-slash collapsing).
17	 */
18	function looksLikeLegacyHandler(url: string): boolean {
19	  const lowerUrl = url.toLowerCase();
20	  return lowerUrl.includes(".ashx");
21	}
22	
23	/**
24	 * Normalize external image URLs using string operations only (no URL object serialization).
25	 * This ensures byte-for-byte identical output on server (Node) and client (browser),
26	 * avoiding hydration mismatches caused by different URL serialization behaviors.
27	 *
28	 * - Trim whitespace
29	 * - Reject overly long / invalid URLs
30	 * - Normalize protocol-relative to https
31	 * - Collapse duplicate slashes in pathname (preserve protocol) - EXCEPT for legacy handlers
32	 * - Strip userinfo (credentials) for security
33	 */
34	export function normalizeExternalImageUrl(imageUrl: string): string {
35	  const trimmed = sanitizeUrlCandidate(imageUrl);
36	  if (!trimmed) {
37	    return "";
38	  }
39	
40	  // Reject overly long URLs - return empty to trigger fallback image rather than broken truncated URL
41	  if (trimmed.length > MAX_URL_LENGTH) {
42	    return "";
43	  }
44	
45	  // Handle protocol-relative
46	  if (trimmed.startsWith("//")) {
47	    return normalizeExternalImageUrl(`https:${trimmed}`);
48	  }
49	
50	  // If it looks like a URL with protocol but not http/https, drop it
51	  if (trimmed.includes("://") && !ABSOLUTE_URL_REGEX.test(trimmed)) {
52	    return "";
53	  }
54	
55	  // If not absolute, return trimmed as-is (relative URLs are allowed)
56	  if (!ABSOLUTE_URL_REGEX.test(trimmed)) {
57	    // Collapse duplicate slashes in relative paths
58	    return trimmed.replace(/\/{2,}/g, "/");
59	  }
60	
61	  // For legacy file handlers, preserve URL structure exactly (don't collapse slashes)
62	  // These handlers may depend on specific URL patterns
63	  if (looksLikeLegacyHandler(trimmed)) {
64	    // Only do minimal normalization: lowercase protocol
65	    const protocolMatch = trimmed.match(/^(https?:\/\/)/i);
66	    if (protocolMatch) {
67	      return (
68	        protocolMatch[1].toLowerCase() + trimmed.slice(protocolMatch[1].length)
69	      );
70	    }
71	    return trimmed;
72	  }
73	
74	  // --- String-based normalization for absolute URLs ---
75	  // Split into protocol + rest
76	  const protocolMatch = trimmed.match(/^(https?:\/\/)/i);
77	  if (!protocolMatch) {
78	    return trimmed;
79	  }
80	  const protocol = protocolMatch[1].toLowerCase(); // normalize to lowercase
81	  let rest = trimmed.slice(protocolMatch[1].length);
82	
83	  // Strip userinfo (user:pass@) if present
84	  const atIndex = rest.indexOf("@");
85	  const slashIndex = rest.indexOf("/");
86	  if (atIndex !== -1 && (slashIndex === -1 || atIndex < slashIndex)) {
87	    rest = rest.slice(atIndex + 1);
88	  }
89	
90	  // Find where the path starts
91	  const pathStart = rest.indexOf("/");
92	  if (pathStart === -1) {
93	    // No path, just host (possibly with query/hash)
94	    return `${protocol}${rest}`;
95	  }
96	
97	  const hostPart = rest.slice(0, pathStart);
98	  let pathAndRest = rest.slice(pathStart);
99	
100	  // Collapse duplicate slashes in pathname only (not in query or hash)
101	  const queryIndex = pathAndRest.indexOf("?");
102	  const hashIndex = pathAndRest.indexOf("#");
103	  const pathEnd =
104	    queryIndex !== -1
105	      ? queryIndex
106	      : hashIndex !== -1
107	      ? hashIndex
108	      : pathAndRest.length;
109	  const pathname = pathAndRest.slice(0, pathEnd).replace(/\/{2,}/g, "/");
110	  const suffix = pathAndRest.slice(pathEnd);
111	
112	  return `${protocol}${hostPart}${pathname}${suffix}`;
113	}
114	
115	/**
116	 * Detect if a URL is a legacy file handler (like ASP.NET .ashx) that doesn't
117	 * tolerate extra query parameters. These handlers:
118	 * - Use complex query strings with tokens/hashes as the file identifier
119	 * - May break if we add ?v=, &w=, &q= parameters
120	 *
121	 * Examples:
122	 * - l-h.cat/utils/obreFitxer.ashx?Fw9EVw48XS4qazCg7ARHmz...
123	 * - Any .ashx handler with existing query params
124	 * - URLs with long hash-like query params (20+ alphanumeric chars)
125	 */
126	export function isLegacyFileHandler(url: string): boolean {
127	  // Check for .ashx (ASP.NET generic handler) with query params
128	  const lowerUrl = url.toLowerCase();
129	  if (lowerUrl.includes(".ashx?")) return true;
130	
131	  const queryIndex = url.indexOf("?");
132	  if (queryIndex === -1) return false;
133	
134	  const hashIndex = url.indexOf("#");
135	  const queryEnd = hashIndex !== -1 ? hashIndex : url.length;
136	  const queryString = url.slice(queryIndex + 1, queryEnd);
137	
138	  // If query string is long and contains hash-like characters, it likely has its own cache key
139	  // Skip URLs that already have a ?v= param (we handle those separately)
140	  if (queryString.includes("v=")) return false;
141	
142	  // Check for long query values that look like hashes/tokens (20+ chars of alphanumeric)
143	  const params = queryString.split("&");
144	  for (const param of params) {
145	    // A value can be the whole parameter if there's no '=', or the part after '='
146	    const value = param.includes("=")
147	      ? param.substring(param.indexOf("=") + 1)
148	      : param;
149	    if (/^[a-zA-Z0-9]{20,}$/.test(value)) {
150	      return true;
151	    }
152	  }
153	  return false;
154	}
155	
156	/**
157	 * Appends (or replaces) a cache-busting query parameter to an image URL.
158	 * Uses string-based operations only to ensure SSR/client hydration consistency.
159	 * Uses the provided cacheKey (event hash, updatedAt, etc.) so that
160	 * the CDN can keep a long TTL while still reflecting new uploads.
161	 *
162	 * Also normalizes protocol-relative URLs (//cdn.example.com/image.jpg) to HTTPS.
163	 *
164	 * Skips adding cache key for URLs that already have complex query strings
165	 * with inherent cache-busting (e.g., l-h.cat file handler URLs).
166	 */
167	export function withImageCacheKey(
168	  imageUrl: string,
169	  cacheKey?: string | number | null
170	): string {
171	  const normalizedUrl = normalizeExternalImageUrl(imageUrl);
172	  if (!normalizedUrl) {
173	    return normalizedUrl;
174	  }
175	
176	  // If no cache key provided, return the normalized URL
177	  if (cacheKey === undefined || cacheKey === null) {
178	    return normalizedUrl;
179	  }
180	
181	  // Skip URLs that are legacy file handlers (e.g., .ashx with token-like query strings)
182	  // These don't tolerate extra query params
183	  if (isLegacyFileHandler(normalizedUrl)) {
184	    return normalizedUrl;
185	  }
186	
187	  const normalizedKey = String(cacheKey).trim();
188	  if (!normalizedKey) {
189	    return normalizedUrl;
190	  }
191	
192	  const encodedKey = encodeURIComponent(normalizedKey);
193	
194	  // Regex to find existing cache param (case-insensitive)
195	  const cacheParamRegex = new RegExp(`([?&])${CACHE_PARAM}=([^&#]*)`, "i");
196	
197	  if (cacheParamRegex.test(normalizedUrl)) {
198	    // Replace existing cache param
199	    return normalizedUrl.replace(
200	      cacheParamRegex,
201	      `$1${CACHE_PARAM}=${encodedKey}`
202	    );
203	  }
204	
205	  // Append new cache param
206	  // Check if URL has a hash - insert before it
207	  const hashIndex = normalizedUrl.indexOf("#");
208	  if (hashIndex !== -1) {
209	    const beforeHash = normalizedUrl.slice(0, hashIndex);
210	    const hash = normalizedUrl.slice(hashIndex);
211	    const separator = beforeHash.includes("?") ? "&" : "?";
212	    return `${beforeHash}${separator}${CACHE_PARAM}=${encodedKey}${hash}`;
213	  }
214	
215	  const separator = normalizedUrl.includes("?") ? "&" : "?";
216	  return `${normalizedUrl}${separator}${CACHE_PARAM}=${encodedKey}`;
217	}
218	
219	// Re-export ImageProxyOptions for consumers importing from this module
220	export type { ImageProxyOptions };
221	
222	/**
223	 * Wrap an external absolute URL with the internal image proxy to avoid mixed content
224	 * and flaky TLS. Keeps relative URLs untouched.
225	 * Uses string operations only to avoid hydration mismatches from URL object serialization.
226	 *
227	 * @param imageUrl - The external image URL to proxy
